{"implementation":"import json
from fractions import Fraction

def solve(case):
    segments = case['segments']
    budget = case['budget']
    n = len(segments)
    names = [s['name'] for s in segments]
    imps = [s['importance'] for s in segments]
    mins = [s['minimum'] for s in segments]
    caps = [s['capacity'] for s in segments]
    allocs = mins[:]
    remaining = budget - sum(mins)
    while remaining > 0:
        best_idx = -1
        best_frac = None
        for i in range(n):
            if allocs[i] < caps[i]:
                frac = Fraction(imps[i], allocs[i] + 1)
                if best_idx == -1 or frac > best_frac:
                    best_idx = i
                    best_frac = frac
        allocs[best_idx] += 1
        remaining -= 1
    by_name = {names[i]: allocs[i] for i in range(n)}
    return {
        'allocations': allocs,
        'by_name': by_name,
        'total': sum(allocs)
    }"}
